function canInspectCandidateBArtifactFamilyStatus(contract = candidateBDefaultPromotionReadinessContract()) {
    const values = candidateBArtifactFamilyStatusInputValues();
    return Boolean(
        contract?.candidate_b_artifact_family_status_admitted
        && candidateBArtifactFamilyStatusEndpointPath(contract)
        && ['bundle', 'runtime'].includes(values.sourceKind)
        && values.bridgeReceiptId
        && !State.candidateBArtifactFamilyStatusPending
    );
}

function canInspectCandidateBVisualLaneStatus(contract = candidateBDefaultPromotionReadinessContract()) {
    const values = candidateBVisualLaneStatusInputValues();
    return Boolean(
        contract?.candidate_b_visual_lane_status_admitted
        && candidateBVisualLaneStatusEndpointPath(contract)
        && values.candidateBRunId
        && values.bridgeReceiptId
        && !State.candidateBVisualLaneStatusPending
    );
}

function canRecordCandidateBBundleDownstreamProof(contract = candidateBDefaultPromotionReadinessContract()) {
    const values = candidateBBundleDownstreamProofInputValues();
    return Boolean(
        contract?.candidate_b_bundle_downstream_proof_admitted
        && candidateBBundleDownstreamProofEndpointPath(contract)
        && values.candidateBBundleId
        && values.bridgeReceiptId
        && values.coverageEvidenceJson
        && !State.candidateBBundleDownstreamProofPending
    );
}

function canRecordCandidateBRuntimeDownstreamProof(contract = candidateBDefaultPromotionReadinessContract()) {
    const values = candidateBRuntimeDownstreamProofInputValues();
    return Boolean(
        contract?.candidate_b_runtime_downstream_proof_admitted
        && candidateBRuntimeDownstreamProofEndpointPath(contract)
        && values.candidateBRunId
        && values.bridgeReceiptId
        && values.coverageEvidenceJson
        && State.candidateBVisualLaneStatus?.status === 'available'
        && State.candidateBVisualLaneStatus?.candidate_b_run_id === values.candidateBRunId
        && State.candidateBVisualLaneStatus?.bridge_receipt_id === values.bridgeReceiptId
        && !State.candidateBRuntimeDownstreamProofPending
    );
}

