function setBusy(button, busy, label) {
    button.disabled = busy;
    if (label) {
        button.textContent = busy ? 'Working...' : label;
    }
}

function setCurrentStepChip(selectedChip) {
    elements.stepChips.forEach((chip) => {
        const selected = chip === selectedChip;
        chip.classList.toggle('current', selected);
        if (selected) {
            chip.setAttribute('aria-current', 'step');
        } else {
            chip.removeAttribute('aria-current');
        }
    });
}

function navigateToStep(chip) {
    const targetId = chip.dataset.stepTarget;
    const target = targetId ? document.getElementById(targetId) : null;
    if (!target) return;
    setCurrentStepChip(chip);
    if (target.closest('.operations-dock')) {
        const operationPanel = target.closest('.workband');
        const operationId = OPERATION_DOCK_STEPS.some((step) => step.id === operationPanel?.id)
            ? operationPanel.id
            : targetId;
        setActiveOperation(operationId, { manual: true });
    }
    target.scrollIntoView({ block: 'start', behavior: 'auto' });
    if (typeof target.focus === 'function') {
        target.focus({ preventScroll: true });
    }
}

function setStepChip(element, active) {
    if (!element) return;
    element.disabled = false;
    element.classList.toggle('active', active);
    element.classList.toggle('unavailable', !active);
    element.dataset.available = active ? 'true' : 'false';
}

function operationDockStatus(step) {
    const sessionReady = Boolean(State.gateB?.session_id || currentSessionId());
    const gateCReady = Boolean(State.gateC?.typing_records?.length || sessionSublayerState().typing_records?.length);
    const authority = selectedResultAuthority();
    switch (step.key) {
    case 'intent':
        return State.preflight
            ? { state: 'live', label: 'preflight passed', detail: 'Intent and source posture are loaded.' }
            : { state: 'ready', label: 'ready', detail: 'Run preflight to load source and material previews.' };
    case 'source_intake':
        return { state: 'ready', label: 'ready', detail: 'Upload, inventory, and preview use existing server-authoritative source-intake APIs.' };
    case 'source_directory':
        if (State.gateB?.session_id) return { state: 'live', label: 'admitted', detail: 'A source-directory preview has been admitted to Gate B.' };
        if (State.sourceDirectoryIngestionBatchStatus?.source_ingestion_batch_id) return { state: 'live', label: 'batch inspected', detail: 'Server source-directory batch status is loaded.' };
        if (State.sourceDirectoryIngestionBatch?.source_ingestion_batch_id) return { state: 'live', label: 'batch scanned', detail: 'Server source-directory batch scan is loaded.' };
        return { state: 'ready', label: 'server configured', detail: 'Scan or inspect the server-configured source-directory batch.' };
    case 'gate_b':
        if (sessionReady) return { state: 'live', label: 'session scoped', detail: 'Gate B has a session-scoped material boundary.' };
        if ((State.materialPreview?.material_candidates || []).length) return { state: 'ready', label: 'review ready', detail: 'Material preview is loaded and ready for Gate B decisions.' };
        return { state: 'blocked', label: 'waiting', detail: 'Run preflight before Gate B review.' };
    case 'gate_c':
        if (gateCReady) return { state: 'live', label: 'typing loaded', detail: 'Gate C typing is available for modality grouping.' };
        if (sessionReady) return { state: 'ready', label: 'preview ready', detail: 'Gate B is committed; Gate C preview can classify material.' };
        return { state: 'blocked', label: 'blocked', detail: 'Commit Gate B before Gate C typing.' };
    case 'plan':
        if (State.planApproval) return { state: 'live', label: 'approved', detail: 'Plan approval state is recorded.' };
        if (State.planPreview) return { state: 'live', label: 'preview loaded', detail: 'Plan preview state is loaded.' };
        if (canPlanPreview()) return { state: 'ready', label: 'preview ready', detail: 'Gate C typing allows plan preview.' };
        return { state: 'blocked', label: 'blocked', detail: 'Commit Gate C typing before plan preview.' };
    case 'results':
        if (recordedResultReview()) return { state: 'live', label: 'review recorded', detail: 'Selected-pass result review is recorded.' };
        if (State.resultStatus?.result_status_available === true) return { state: 'ready', label: 'status ready', detail: 'Selected-pass result status can be reviewed.' };
        if (authority.selected) return { state: 'ready', label: 'selected pass', detail: 'A selected pass exists; inspect terminal result status when available.' };
        return { state: 'blocked', label: 'blocked', detail: 'Execution/result authority is not available in the current session.' };
    case 'package':
        if (packageReviewSubmitState()?.package_review_state || packageReviewSubmitState()?.state) return { state: 'live', label: 'package state', detail: 'Package review state is recorded.' };
        if (canInspectPackageReviewPreview() || canCommitPackageConstruction() || canSubmitPackageReview()) return { state: 'ready', label: 'package ready', detail: 'Package preview, construction, or review controls are available.' };
        return { state: 'blocked', label: 'blocked', detail: 'Approve selected-pass result review before package review.' };
    case 'handoff':
        if (recordedHandoffExportPrepare()) return { state: 'live', label: 'prepared', detail: 'Internal handoff/export preparation is recorded.' };
        if (mixedSourceHandoffExportPrepareAuthorityPacket()) return { state: 'ready', label: 'material authority ready', detail: 'Mixed-source material authority can prepare a reference-envelope handoff.' };
        if (State.sessionSummary?.handoff_export_prepare?.available === true) return { state: 'ready', label: 'prepare ready', detail: 'Package review approval can be prepared for handoff/export.' };
        return { state: 'blocked', label: 'blocked', detail: 'Approve package review before handoff/export preparation.' };
    case 'aps':
        if (recordedApsHandoffDispatch()) return { state: 'live', label: 'dispatched', detail: 'APS handoff dispatch is recorded.' };
        if (apsHandoffDispatchState()?.available === true) return { state: 'ready', label: 'dispatch ready', detail: 'Prepared handoff/export can dispatch the APS evidence bundle.' };
        return { state: 'blocked', label: 'blocked', detail: 'Prepare handoff/export before APS dispatch.' };
    case 'external':
        if (recordedMixedSourceExternalExportDownloadDelivery()) return { state: 'live', label: 'mixed delivered', detail: 'Mixed-source package delivery has been requested.' };
        if (recordedExternalExportDownloadDelivery()) return { state: 'live', label: 'delivered', detail: 'Same-origin delivery has been requested.' };
        if (mixedSourceExternalExportDownloadDeliveryAuthorityPacket()) return { state: 'ready', label: 'mixed delivery ready', detail: 'P19 mixed-source readiness can deliver the review-facing package.' };
        if (mixedSourceExternalExportDownloadReadinessState()) return { state: 'blocked', label: 'mixed blocked', detail: 'Mixed-source delivery needs complete readiness and package authority.' };
        if (recordedExternalExportDownloadPrepare()) return { state: 'ready', label: 'delivery ready', detail: 'External export/download readiness can be delivered.' };
        if (canSubmitExternalExportDownloadPrepare()) return { state: 'ready', label: 'prepare ready', detail: 'Prepared source-directory handoff can prepare external export/download readiness.' };
        if (State.sessionSummary?.external_export_download?.available === true) return { state: 'ready', label: 'prepare ready', detail: 'APS dispatch can prepare external export/download readiness.' };
        return { state: 'blocked', label: 'blocked', detail: 'Dispatch APS handoff before external export/download readiness.' };
    case 'analysis_products': {
        const inv = currentAnalysisProductInventoryProjection();
        const st = analysisProductInventoryProjectionStatus(inv);
        if (inv && Array.isArray(st.analystProducts) && st.analystProducts.length > 0) {
            return { state: 'live', label: 'products present', detail: 'Session has 3C analysis products to author, promote, or generate.' };
        }
        if (inv) {
            return { state: 'ready', label: 'workspace ready', detail: 'Author drafts, build working sets, run deterministic generation.' };
        }
        return { state: 'blocked', label: 'awaiting session', detail: 'Load a session summary to use the 3C product workspace.' };
    }
    default:
        return { state: 'blocked', label: 'unknown', detail: 'Operation state is not reported.' };
    }
}

function renderOperationDockSummary(activeStep, status) {
    if (!elements.operationsDockSummary || !activeStep || !status) return;
    const activeIndex = OPERATION_DOCK_STEPS.findIndex((step) => step.id === activeStep.id);
    const positionLabel = activeIndex >= 0
        ? `${activeIndex + 1} of ${OPERATION_DOCK_STEPS.length}`
        : 'operation';
    const stateLabel = status.state === 'live'
        ? 'Live-backed'
        : status.state === 'ready'
            ? 'Action-ready'
            : 'Unavailable';
    elements.operationsDockSummary.dataset.operationState = status.state;
    elements.operationsDockSummary.dataset.canvasTarget = activeStep.canvasTarget || '';
    elements.operationsDockSummary.innerHTML = `
        <div class="operation-summary-eyebrow">
            <span>${escapeHtml(positionLabel)}</span>
            <span>${escapeHtml(activeStep.canvasLink || 'Layer 3 operation')}</span>
        </div>
        <div class="operation-summary-main">
            <h3>${escapeHtml(activeStep.label)}</h3>
            <span class="operation-summary-state">${escapeHtml(stateLabel)}: ${escapeHtml(status.label)}</span>
        </div>
        <div class="operation-summary-canvas-role">
            <span>Canvas role</span>
            <strong>${escapeHtml(activeStep.canvasRole || activeStep.canvasLink || 'Layer 3 canvas')}</strong>
        </div>
        <p>${escapeHtml(status.detail)}</p>
    `;
}

function renderOperationsDock() {
    if (!elements.operationsDock || !elements.operationsDockNav) return;
    const availableSteps = OPERATION_DOCK_STEPS.filter((step) => {
        if (!document.getElementById(step.id)) return false;
        if (step.key !== 'source_directory') return true;
        return operationDockStatus(step).state === 'live';
    });
    if (!availableSteps.some((step) => step.id === State.activeOperationId)) {
        State.activeOperationId = availableSteps[0]?.id || '';
        State.operationDockManual = false;
    }
    if (!State.operationDockManual) {
        const currentStep = availableSteps.find((step) => step.id === State.activeOperationId);
        const currentStatus = currentStep ? operationDockStatus(currentStep) : null;
        const shouldSuggestStep = !currentStatus || currentStatus.state === 'blocked';
        const suggestedStep = [...availableSteps]
            .reverse()
            .find((step) => step.key !== 'source_intake' && operationDockStatus(step).state === 'live')
            || availableSteps.find((step) => step.key === 'source_intake')
            || availableSteps.find((step) => step.key === 'intent')
            || [...availableSteps].reverse().find((step) => operationDockStatus(step).state !== 'blocked');
        if (shouldSuggestStep && suggestedStep) State.activeOperationId = suggestedStep.id;
    }
    elements.operationsDock.dataset.activeOperation = State.activeOperationId;
    const activeStep = availableSteps.find((step) => step.id === State.activeOperationId);
    const activeStatus = activeStep ? operationDockStatus(activeStep) : null;
    if (elements.sublayerMapPanel) {
        elements.sublayerMapPanel.dataset.activeOperationCanvas = activeStep?.canvasTarget || '3a';
        elements.sublayerMapPanel.dataset.activeOperationKey = activeStep?.key || 'intent';
    }
    renderOperationDockSummary(activeStep, activeStatus);
    elements.operationsDockNav.innerHTML = availableSteps.map((step, index) => {
        const status = operationDockStatus(step);
        const selected = step.id === State.activeOperationId;
        return `
            <button class="operation-dock-tab ${selected ? 'active' : ''}" type="button" role="tab"
                id="operation-tab-${escapeHtml(step.key)}"
                aria-controls="${escapeHtml(step.id)}"
                aria-selected="${selected ? 'true' : 'false'}"
                tabindex="${selected ? '0' : '-1'}"
                data-operation-target="${escapeHtml(step.id)}"
                data-operation-state="${escapeHtml(status.state)}"
                data-operation-index="${index}">
                <span class="operation-dock-tab-label">${escapeHtml(step.shortLabel)}</span>
                <span class="operation-dock-tab-state">${escapeHtml(status.label)}</span>
                <span class="operation-dock-tab-detail">${escapeHtml(status.detail)}</span>
            </button>
        `;
    }).join('');
    availableSteps.forEach((step) => {
        const panel = document.getElementById(step.id);
        const status = operationDockStatus(step);
        const selected = step.id === State.activeOperationId;
        panel.classList.toggle('operation-panel-active', selected);
        panel.classList.toggle('operation-panel-inactive', !selected);
        panel.dataset.operationState = status.state;
        panel.dataset.operationActive = selected ? 'true' : 'false';
        panel.setAttribute('role', 'tabpanel');
        panel.setAttribute('aria-labelledby', `operation-tab-${step.key}`);
    });
    Array.from(elements.operationsDockNav.querySelectorAll('.operation-dock-tab')).forEach((button) => {
        button.addEventListener('click', () => setActiveOperation(button.dataset.operationTarget, { focusPanel: true, manual: true }));
        button.addEventListener('keydown', handleOperationDockKeydown);
    });
}

function setActiveOperation(operationId, { focusPanel = false, focusButton = false, manual = false } = {}) {
    if (manual) State.operationDockManual = true;
    if (!operationId || State.activeOperationId === operationId) {
        if (focusPanel) document.getElementById(operationId)?.focus({ preventScroll: true });
        return;
    }
    State.activeOperationId = operationId;
    renderOperationsDock();
    const panel = document.getElementById(operationId);
    const button = elements.operationsDockNav?.querySelector(`[data-operation-target="${CSS.escape(operationId)}"]`);
    if (focusButton && button) button.focus();
    if (focusPanel && panel) {
        panel.scrollIntoView({ block: 'nearest', inline: 'nearest', behavior: 'auto' });
        panel.focus({ preventScroll: true });
    }
}

function handleOperationDockKeydown(event) {
    const keys = ['ArrowRight', 'ArrowDown', 'ArrowLeft', 'ArrowUp', 'Home', 'End'];
    if (!keys.includes(event.key)) return;
    const buttons = Array.from(elements.operationsDockNav?.querySelectorAll('.operation-dock-tab') || []);
    const currentIndex = buttons.indexOf(event.currentTarget);
    if (currentIndex < 0) return;
    event.preventDefault();
    let nextIndex = currentIndex;
    if (event.key === 'Home') {
        nextIndex = 0;
    } else if (event.key === 'End') {
        nextIndex = buttons.length - 1;
    } else {
        const delta = event.key === 'ArrowRight' || event.key === 'ArrowDown' ? 1 : -1;
        nextIndex = (currentIndex + delta + buttons.length) % buttons.length;
    }
    setActiveOperation(buttons[nextIndex].dataset.operationTarget, { focusButton: true, manual: true });
}

function providerPrivateSignedUrlPanelState() {
    if (State.providerPrivateSignedUrlError) {
        const errorCode = State.providerPrivateSignedUrlError.error_code
            || State.providerPrivateSignedUrlError.error?.code
            || 'provider_private_signed_url_blocked';
        const errorMessage = State.providerPrivateSignedUrlError.message
            || State.providerPrivateSignedUrlError.error?.message
            || 'Provider-private signed URL control is blocked.';
        return { label: errorCode, pill: 'blocked', message: errorMessage };
    }
    const stateName = providerPrivateSignedUrlLatestState();
    if (stateName === 'provider_private_signed_url_revoked') {
        return { label: stateName, pill: 'ready', message: 'Provider-private signed URL receipt has been revoked; a replacement can be prepared.' };
    }
    if (stateName === 'provider_private_signed_url_expired') {
        return { label: stateName, pill: 'ready', message: 'Provider-private signed URL receipt has expired; a replacement can be prepared.' };
    }
    if (State.providerPrivateSignedUrlUse?.delivery_use_decision === 'allowed') {
        const usedState = stateName || 'provider_private_signed_url_used';
        return { label: 'provider_private_signed_url_use_allowed', pill: 'ready', message: `${usedState}; server recorded the redacted provider-private use decision; raw provider URL delivery remains blocked.` };
    }
    if (stateName === 'provider_private_signed_url_prepared') {
        const message = providerPrivateSignedUrlUsePath()
            ? 'Provider-private signed URL receipt is prepared; server-owned redacted use is available for this source-directory artifact.'
            : 'Provider-private signed URL receipt is prepared; use remains closed for this lane.';
        return { label: stateName, pill: 'ready', message };
    }
    if (providerPrivateSignedUrlUsesSourceDirectoryHybridFamily() && sourceDirectoryHybridProviderPrivateSignedUrlReady()) {
        return { label: 'provider_private_signed_url_ui_ready', pill: 'ready', message: 'Ready to prepare a redacted provider-private signed URL receipt from source-directory hybrid delivery authority.' };
    }
    if (providerPrivateSignedUrlUsesSourceDirectoryPackageFamily() && sourceDirectoryPackageSupersessionProviderPrivateSignedUrlReady()) {
        return { label: 'provider_private_signed_url_ui_ready', pill: 'ready', message: 'Ready to prepare a redacted provider-private signed URL receipt from source-directory package supersession authority.' };
    }
    if (recordedExternalExportDownloadPrepare() && externalExportDownloadDeliveryUiAdmitted()) {
        return { label: 'provider_private_signed_url_ui_ready', pill: 'ready', message: 'Ready to prepare a redacted provider-private signed URL receipt.' };
    }
    return { label: 'provider_private_signed_url_ui_unavailable', pill: 'blocked', message: 'Prepare external export/download readiness before provider-private signed URL controls.' };
}

function providerPrivateSignedUrlDisplayValue(value) {
    if (Array.isArray(value)) return value.length ? value.join(', ') : 'none';
    if (value === true) return 'true';
    if (value === false) return 'false';
    return value ?? 'none';
}

function renderProviderPrivateSignedUrlPanel() {
    const provider = providerPrivateSignedUrlAuthorityState() || {};
    const panelState = providerPrivateSignedUrlPanelState();
    const audit = provider.audit_receipt || {};
    const rows = {
        selected_artifact_family: providerPrivateSignedUrlSelectedArtifactFamily(),
        active_artifact_family: providerPrivateSignedUrlActiveArtifactFamily(),
        receipt_id: provider.provider_signed_url_receipt_id,
        provider_private_state: provider.provider_signed_url_state,
        delivery_mode: provider.delivery_mode,
        provider_url_redacted: provider.provider_url_redacted,
        expires_at: provider.provider_url_expires_at,
        replay_policy: provider.provider_url_replay_policy,
        use_count: provider.provider_url_use_count,
        max_use_count: provider.provider_url_max_use_count,
        revoked: provider.provider_url_revoked,
        delivery_use_decision: provider.delivery_use_decision,
        delivery_use_mode: provider.delivery_use_mode,
        source_artifact_hash: provider.source_artifact_hash,
        source_artifact_size_bytes: provider.source_artifact_size_bytes,
        audit_receipt_id: audit.audit_event_id || audit.provider_private_signed_url_audit_event_id,
        audit_reason_code: audit.reason_code,
        next_allowed_actions: provider.next_allowed_actions,
        prepare_route: providerPrivateSignedUrlPreparePath(),
        status_route: providerPrivateSignedUrlStatusPath(),
        use_route: providerPrivateSignedUrlUsePath() || 'closed_not_implemented',
        revoke_route: providerPrivateSignedUrlRevokePath(),
    };
    elements.providerPrivateSignedUrlPanel.innerHTML = `
        <div class="result-review-status">
            <span class="status-pill ${escapeHtml(panelState.pill)}">${escapeHtml(panelState.label)}</span>
            <span class="rail-label">${escapeHtml(panelState.message)}</span>
        </div>
        <div class="result-review-grid">
            ${Object.entries(rows).map(([label, value]) => `
                <section class="result-review-card">
                    <strong>${escapeHtml(label.replace(/_/g, ' '))}</strong>
                    <p>${escapeHtml(providerPrivateSignedUrlDisplayValue(value))}</p>
                </section>
            `).join('')}
        </div>
    `;
    elements.providerPrivateSignedUrlPrepare.disabled = !canPrepareProviderPrivateSignedUrl();
    elements.providerPrivateSignedUrlStatus.disabled = !canInspectProviderPrivateSignedUrl();
    elements.providerPrivateSignedUrlUse.disabled = !canUseProviderPrivateSignedUrl();
    elements.providerPrivateSignedUrlRevoke.disabled = !canRevokeProviderPrivateSignedUrl();
}

function providerPublicUrlPanelState() {
    if (State.providerPublicUrlError) {
        return { label: State.providerPublicUrlError.error_code || 'provider_public_url_blocked', pill: 'blocked', message: State.providerPublicUrlError.message || 'Provider-public URL control is blocked.' };
    }
    const stateName = providerPublicUrlLatestState();
    if (stateName === 'provider_public_url_revoked') {
        return { label: stateName, pill: 'ready', message: 'Provider-public URL receipt has been revoked; a replacement can be prepared from provider-private authority.' };
    }
    if (stateName === 'provider_public_url_expired') {
        return { label: stateName, pill: 'ready', message: 'Provider-public URL receipt has expired; a replacement can be prepared from provider-private authority.' };
    }
    if (State.providerPublicUrlUse?.delivery_use_decision === 'allowed') {
        return { label: 'provider_public_url_use_allowed', pill: 'ready', message: 'Server allowed the redacted provider-public use decision; raw URL delivery remains blocked.' };
    }
    if (State.providerPublicUrlUse?.delivery_use_decision === 'denied') {
        const reason = State.providerPublicUrlUse.delivery_use_denied_reason || 'provider_public_url_use_denied';
        return { label: 'provider_public_url_use_denied', pill: 'blocked', message: `Server denied the redacted provider-public use decision: ${reason}.` };
    }
    if (stateName === 'provider_public_url_prepared') {
        return { label: stateName, pill: 'ready', message: 'Provider-public URL receipt is prepared; the redacted use-decision control is available while raw public URL exposure remains closed.' };
    }
    const sourceDirectoryBlockReason = sourceDirectoryProviderPublicUrlBlockReason();
    if (
        providerPrivateSignedUrlReceiptId()
        && providerPrivateSignedUrlLatestState() === 'provider_private_signed_url_prepared'
        && sourceDirectoryBlockReason
    ) {
        return {
            label: 'provider_public_url_source_directory_provider_private_not_admitted',
            pill: 'blocked',
            message: `Provider-public URL prepare is not admitted for this source-directory provider-private authority: ${sourceDirectoryBlockReason}.`,
        };
    }
    if (providerPrivateSignedUrlReceiptId() && providerPrivateSignedUrlLatestState() === 'provider_private_signed_url_prepared') {
        return { label: 'provider_public_url_ui_ready', pill: 'ready', message: 'Ready to prepare a server-redacted provider-public URL receipt.' };
    }
    return { label: 'provider_public_url_ui_unavailable', pill: 'blocked', message: 'Prepare a provider-private receipt before provider-public URL controls.' };
}

function providerPublicUrlDisplayValue(value) {
    if (Array.isArray(value)) return value.length ? value.join(', ') : 'none';
    if (value === true) return 'true';
    if (value === false) return 'false';
    return value ?? 'none';
}

// ── W1-S9: Package supersession history read-only projection ──

/**
 * Returns true when at least one supersession authority record is in State.
 * Fail-closed: absent authority → blocked panel.
 */
function packageSupersessionHistoryAuthorityPresent() {
    return Boolean(
        State.replacementPackageSetAuthority
        || State.packageSupersessionCommit
        || State.replacementPackageArtifactMaterialization
    );
}

/**
 * Returns the label / pill for the history projection panel.
 */
function packageSupersessionHistoryPanelState() {
    if (!packageSupersessionHistoryAuthorityPresent()) {
        return {
            label: 'package_supersession_history_blocked',
            pill: 'blocked',
            message: 'Replacement-package authority or supersession commit must be present.',
        };
    }
    const commit = packageSupersessionCommitState() || {};
    const authority = replacementPackageSetAuthorityState() || {};
    if (commit.package_supersession_commit_id) {
        return {
            label: 'package_supersession_commit_recorded',
            pill: 'ok',
            message: 'Package supersession commit is recorded in session State.',
        };
    }
    if (authority.replacement_package_set_authority_id) {
        return {
            label: 'replacement_package_set_authority_recorded',
            pill: 'ready',
            message: 'Replacement-package set authority is recorded; supersession commit pending.',
        };
    }
    return {
        label: 'package_supersession_history_partial',
        pill: 'preview',
        message: 'Replacement artifact materialization recorded; authority and commit pending.',
    };
}

/**
 * Renders the W1-S9 read-only supersession history projection panel.
 *
 * No backend GET/history route exists for supersession records — this panel
 * reflects only in-session State (replacementPackageSetAuthority,
 * packageSupersessionCommit). A dedicated history projection route has not
 * been implemented; when one is added, this panel can be extended to hydrate
 * from it.
 */
function renderPackageSupersessionHistoryPanel() {
    const panel = elements.packageSupersessionHistoryPanel;
    if (!panel) return;

    const panelState = packageSupersessionHistoryPanelState();

    if (!packageSupersessionHistoryAuthorityPresent()) {
        panel.innerHTML = `
            <div class="result-review-status">
                <span class="status-pill blocked">${escapeHtml(panelState.label)}</span>
                <span class="rail-label">${escapeHtml(panelState.message)}</span>
            </div>
        `;
        return;
    }

    const materialization = replacementPackageArtifactMaterializationState() || {};
    const authority = replacementPackageSetAuthorityState() || {};
    const commit = packageSupersessionCommitState() || {};

    panel.innerHTML = `
        <div class="result-review-status">
            <span class="status-pill ${escapeHtml(panelState.pill)}">${escapeHtml(panelState.label)}</span>
            <span class="rail-label">${escapeHtml(panelState.message)}</span>
        </div>
        <div class="result-review-grid package-supersession-history-grid">
            <section class="result-review-card">
                <strong>History Projection Notice</strong>
                <ul>
                    ${fieldItem('read-only surface', 'rendered_package_supersession_history_read_only_projection', { code: true })}
                    ${fieldItem('browser durable authority', false)}
                    ${fieldItem('value reveal enabled', false)}
                    ${fieldItem('production readiness claimed', false)}
                    ${fieldItem('backend history route', 'none — no GET/history route exists in package.py; projection reflects session State only')}
                </ul>
            </section>
            <section class="result-review-card">
                <strong>Replacement Artifact Materialization</strong>
                <ul>
                    ${fieldItem('materialization id', materialization.replacement_artifact_materialization_id, { code: true })}
                    ${fieldItem('mode', materialization.replacement_package_artifact_materialization_mode, { code: true })}
                    ${fieldItem('namespace', materialization.artifact_namespace, { code: true })}
                    ${fieldItem('replacement set id', materialization.replacement_package_set_id, { code: true })}
                    ${fieldItem('replacement set hash', materialization.replacement_package_set_hash, { code: true })}
                    ${fieldItem('next state', materialization.next_state)}
                    ${fieldItem('status', materialization.status)}
                </ul>
            </section>
            <section class="result-review-card">
                <strong>Replacement Package Set Authority</strong>
                <ul>
                    ${fieldItem('authority id', authority.replacement_package_set_authority_id, { code: true })}
                    ${fieldItem('replacement set id', authority.replacement_package_set_id, { code: true })}
                    ${fieldItem('replacement set hash', authority.replacement_package_set_hash, { code: true })}
                    ${fieldItem('authority basis hash', authority.authority_basis_hash, { code: true })}
                    ${fieldItem('next state', authority.next_state)}
                    ${fieldItem('status', authority.status)}
                </ul>
            </section>
            <section class="result-review-card">
                <strong>Package Supersession Commit</strong>
                <ul>
                    ${fieldItem('commit id', commit.package_supersession_commit_id, { code: true })}
                    ${fieldItem('commit mode', commit.package_supersession_commit_mode, { code: true })}
                    ${fieldItem('commit basis hash', commit.commit_basis_hash, { code: true })}
                    ${fieldItem('downstream dependency hash', commit.downstream_dependency_hash, { code: true })}
                    ${fieldItem('next state', commit.next_state)}
                    ${fieldItem('status', commit.status)}
                </ul>
            </section>
            ${renderErrorCard(State.replacementPackageSetAuthorityError || State.packageSupersessionCommitError || State.replacementPackageArtifactMaterializationError)}
        </div>
    `;
}

// ── W1-S7: Signed-reference & provider-private URL revocation audit panel ──

/**
 * Returns true when there is enough server authority to show the audit surface.
 * Fail-closed: absent readiness → blocked panel, no controls enabled.
 */
function signedReferenceRevocationAuditAuthorityPresent() {
    return Boolean(
        externalExportDownloadPrepareState()
        || State.providerPrivateSignedUrlPrepare
        || State.providerPrivateSignedUrlStatus
        || State.providerPrivateSignedUrlRevoke
    );
}

/**
 * Returns the current panel state object for the read-only audit surface.
 */
function signedReferenceRevocationAuditPanelState() {
    if (!signedReferenceRevocationAuditAuthorityPresent()) {
        return {
            label: 'signed_reference_revocation_audit_blocked',
            pill: 'blocked',
            message: 'External export download readiness authority is not available — audit surface is blocked.',
        };
    }
    if (State.signedReferenceRevocationAuditRevokeError) {
        return {
            label: State.signedReferenceRevocationAuditRevokeError.error_code || 'signed_reference_revocation_audit_revoke_blocked',
            pill: 'blocked',
            message: State.signedReferenceRevocationAuditRevokeError.message || 'Revocation was rejected by the server.',
        };
    }
    const receiptId = providerPrivateSignedUrlReceiptId();
    const latestState = providerPrivateSignedUrlLatestState();
    if (latestState === 'provider_private_signed_url_revoked') {
        return {
            label: 'signed_reference_revocation_recorded',
            pill: 'ok',
            message: 'Provider-private signed URL receipt has been revoked. Audit record is final.',
        };
    }
    if (receiptId) {
        return {
            label: 'signed_reference_revocation_audit_ready',
            pill: 'ready',
            message: 'Provider-private signed URL receipt is present. Revocation control is available.',
        };
    }
    const signed = State.externalExportDownloadSignedReference || {};
    if (signed.signed_reference_receipt_id) {
        return {
            label: 'signed_reference_present_provider_private_pending',
            pill: 'preview',
            message: 'Signed-reference token is recorded. Prepare a provider-private receipt to enable revocation control.',
        };
    }
    return {
        label: 'signed_reference_revocation_audit_no_receipt',
        pill: 'preview',
        message: 'External export readiness is present but no signed-reference or provider-private receipt has been prepared yet.',
    };
}

/**
 * Returns true when the revoke button should be enabled.
 * Mirrors the same gate as canRevokeProviderPrivateSignedUrl() but adds
 * the operator confirmation check.
 */
function canSubmitSignedReferenceRevocationAuditRevoke() {
    const confirmation = String(
        elements.signedReferenceRevocationAuditOperatorConfirmation?.value || ''
    ).trim();
    return Boolean(
        confirmation === 'REVOKE'
        && canRevokeProviderPrivateSignedUrl()
        && !State.signedReferenceRevocationAuditRevokePending
    );
}

/**
 * Redacts any token/URL value before display.
 * Non-empty strings are replaced with a character-count indicator.
 * null/undefined → 'none'. All other values → String(value).
 */
function signedReferenceAuditRedact(value) {
    if (value == null) return 'none';
    if (typeof value === 'string' && value.length > 0) {
        return `[redacted: ${value.length} chars]`;
    }
    return String(value);
}

/**
 * Renders the read-only audit listing panel (signed-reference tokens + provider-private URL state).
 */
function renderSignedReferenceRevocationAuditPanel() {
    const panel = elements.signedReferenceRevocationAuditPanel;
    if (!panel) return;
    const panelState = signedReferenceRevocationAuditPanelState();

    if (!signedReferenceRevocationAuditAuthorityPresent()) {
        panel.innerHTML = `
            <div class="result-review-status">
                <span class="status-pill blocked">${escapeHtml(panelState.label)}</span>
                <span class="rail-label">${escapeHtml(panelState.message)}</span>
            </div>
        `;
        return;
    }

    const external = externalExportDownloadPrepareState() || {};
    const signed = State.externalExportDownloadSignedReference || {};
    const provider = providerPrivateSignedUrlAuthorityState() || {};
    const providerRevoke = State.providerPrivateSignedUrlRevoke || {};

    panel.innerHTML = `
        <div class="result-review-status">
            <span class="status-pill ${escapeHtml(panelState.pill)}">${escapeHtml(panelState.label)}</span>
            <span class="rail-label">${escapeHtml(panelState.message)}</span>
        </div>
        <div class="result-review-grid">
            <section class="result-review-card">
                <strong>Signed Reference Audit</strong>
                <ul>
                    ${fieldItem('receipt id', signed.signed_reference_receipt_id, { code: true })}
                    ${fieldItem('token id', signed.signed_reference_token_id, { code: true })}
                    ${fieldItem('token prefix', signed.signed_reference_token_prefix, { code: true })}
                    ${fieldItem('state', signed.signed_reference_state)}
                    ${fieldItem('revoked', signed.signed_reference_revoked)}
                    ${fieldItem('use count', signed.signed_reference_use_count)}
                    ${fieldItem('max use count', signed.signed_reference_max_use_count)}
                    ${fieldItem('replay policy', signed.signed_reference_replay_policy)}
                    ${fieldItem('expires at', signed.signed_reference_expires_at)}
                    ${fieldItem('audit event id', signed.signed_reference_audit_event_id, { code: true })}
                    ${fieldItem('token', signedReferenceAuditRedact(signed.signed_reference_token), { code: true })}
                </ul>
            </section>
            <section class="result-review-card">
                <strong>Provider-Private Receipt</strong>
                <ul>
                    ${fieldItem('receipt id', provider.provider_signed_url_receipt_id, { code: true })}
                    ${fieldItem('state', provider.provider_signed_url_state)}
                    ${fieldItem('delivery mode', provider.delivery_mode)}
                    ${fieldItem('url redacted', provider.provider_url_redacted, { code: true })}
                    ${fieldItem('expires at', provider.provider_url_expires_at)}
                    ${fieldItem('use count', provider.provider_url_use_count)}
                    ${fieldItem('max use count', provider.provider_url_max_use_count)}
                    ${fieldItem('revoked', provider.provider_url_revoked)}
                    ${fieldItem('revocation supported', provider.provider_url_revocation_supported)}
                    ${fieldItem('artifact hash', provider.source_artifact_hash, { code: true })}
                    ${fieldItem('artifact size bytes', provider.source_artifact_size_bytes)}
                </ul>
            </section>
            <section class="result-review-card">
                <strong>Readiness Gate</strong>
                <ul>
                    ${fieldItem('readiness ref', external.external_export_download_record_ref, { code: true })}
                    ${fieldItem('descriptor ref', external.export_download_descriptor_ref, { code: true })}
                    ${fieldItem('readiness state', externalExportDownloadStateName(external))}
                    ${fieldItem('pass type', external.pass_type)}
                    ${fieldItem('method', external.method)}
                    ${fieldItem('source gate', external.source_gate)}
                </ul>
            </section>
            <section class="result-review-card">
                <strong>Revocation Record</strong>
                <ul>
                    ${fieldItem('revocation recorded', providerRevoke.revocation_recorded)}
                    ${fieldItem('idempotency key', providerRevoke.revocation_idempotency_key, { code: true })}
                    ${fieldItem('receipt id', providerRevoke.provider_signed_url_receipt_id, { code: true })}
                    ${fieldItem('final state', providerRevoke.provider_signed_url_state)}
                    ${fieldItem('next state', providerRevoke.next_state)}
                    ${fieldItem('next allowed actions', Array.isArray(providerRevoke.next_allowed_actions) ? providerRevoke.next_allowed_actions.join(', ') : providerRevoke.next_allowed_actions)}
                </ul>
            </section>
            <section class="result-review-card">
                <strong>Still Disabled</strong>
                <div class="downstream-locks">${renderDownstreamLocks([
                    'download_url_exposure',
                    'provider_public_url_governance',
                    'connector_dispatch',
                    'raw_token_display',
                    'byte_streaming',
                    'provider_network_write',
                ])}</div>
            </section>
            ${renderErrorCard(State.signedReferenceRevocationAuditRevokeError)}
        </div>
    `;
}

/**
 * Renders the revocation control sub-panel and manages button enable state.
 */
function renderSignedReferenceRevocationAuditRevokePanel() {
    const revokePanel = elements.signedReferenceRevocationAuditRevokePanel;
    const revokeSubmit = elements.signedReferenceRevocationAuditRevokeSubmit;
    if (!revokePanel) return;

    if (!signedReferenceRevocationAuditAuthorityPresent()) {
        revokePanel.innerHTML = `<div class="empty-panel">Provider-private signed URL receipt authority is not available — revocation control is blocked.</div>`;
        if (revokeSubmit) revokeSubmit.disabled = true;
        return;
    }

    const receiptId = providerPrivateSignedUrlReceiptId();
    const latestState = providerPrivateSignedUrlLatestState();
    const providerRevoke = State.providerPrivateSignedUrlRevoke || {};

    if (!receiptId) {
        revokePanel.innerHTML = `<div class="empty-panel">No provider-private receipt is available for revocation. Prepare a receipt first using the provider-private signed URL controls above.</div>`;
        if (revokeSubmit) revokeSubmit.disabled = true;
        return;
    }

    const revokeState = {
        label: latestState === 'provider_private_signed_url_revoked'
            ? 'revocation_already_recorded'
            : 'revocation_control_ready',
        pill: latestState === 'provider_private_signed_url_revoked' ? 'ok' : 'ready',
    };

    revokePanel.innerHTML = `
        <div class="result-review-status">
            <span class="status-pill ${escapeHtml(revokeState.pill)}">${escapeHtml(revokeState.label)}</span>
        </div>
        <div class="result-review-grid">
            <section class="result-review-card">
                <strong>Revoke Target</strong>
                <ul>
                    ${fieldItem('receipt id', receiptId, { code: true })}
                    ${fieldItem('current state', latestState)}
                    ${fieldItem('revoke path', providerPrivateSignedUrlRevokePath(), { code: true })}
                    ${fieldItem('operator decision', 'revoke_provider_private_signed_url')}
                    ${fieldItem('revocation recorded', providerRevoke.revocation_recorded)}
                    ${fieldItem('idempotency key', providerRevoke.revocation_idempotency_key, { code: true })}
                </ul>
            </section>
        </div>
    `;

    if (revokeSubmit) {
        revokeSubmit.disabled = !canSubmitSignedReferenceRevocationAuditRevoke();
    }
}

// ---------------------------------------------------------------------------
// W2-S8: Provider-private download control panel
// ---------------------------------------------------------------------------

/**
 * Returns true when the download control should be shown (active prepared receipt).
 * Fail-closed: absent authority keeps panel in blocked state.
 */
function providerPrivateDownloadControlAuthorityPresent() {
    const provider = providerPrivateSignedUrlAuthorityState();
    if (!provider) return false;
    const state = provider.provider_signed_url_state;
    // Only offer the download affordance when a receipt is in prepared state.
    return state === 'provider_private_signed_url_prepared';
}

/**
 * Renders the download control panel.
 *
 * LEAKAGE RULES enforced here:
 *   - The signed URL is held only in State.providerPrivateDownloadAnchorUrl (in-memory).
 *   - It is placed in anchor.href only at click time, never rendered into textContent.
 *   - It is never written to localStorage/sessionStorage.
 *   - It is never logged to the console.
 *   - The panel's own data-download-url-exposed="true" attribute (set in HTML) honestly
 *     reflects that this surface exposes a download affordance. The audit panel's
 *     data-download-url-exposed="false" attribute is NOT modified here.
 */
function renderProviderPrivateDownloadControlPanel() {
    const panel = elements.providerPrivateDownloadControlPanel;
    if (!panel) return;

    if (!providerPrivateDownloadControlAuthorityPresent()) {
        panel.innerHTML = `<div class="empty-panel">Provider-private download control is blocked until signed URL receipt authority is present.</div>`;
        return;
    }

    const provider = providerPrivateSignedUrlAuthorityState() || {};
    const receiptId = provider.provider_signed_url_receipt_id || '';
    const expiresAt = provider.provider_url_expires_at || '';
    const recipientScope = provider.recipient_scope || '';
    const hasInMemoryUrl = Boolean(State.providerPrivateDownloadAnchorUrl);
    const isPending = Boolean(State.providerPrivateDownloadPending);
    const fetchError = State.providerPrivateDownloadError || null;
    const redactedNotice = State.providerPrivateDownloadRedactedNotice || null;

    // Status pill and message — three states: url ready, redacted (no url), awaiting arm.
    const pillClass = hasInMemoryUrl ? 'ok' : (redactedNotice ? 'blocked' : 'preview');
    const pillLabel = hasInMemoryUrl
        ? 'download_ready'
        : (redactedNotice ? 'provider_private_download_redacted' : 'provider_private_download_control_ready');
    const railMessage = hasInMemoryUrl
        ? 'Download anchor is ready — click the link to retrieve the package. The URL is not rendered as text.'
        : (redactedNotice
            ? escapeHtml(redactedNotice)
            : 'Operator confirmation required before download anchor is armed.');

    panel.innerHTML = `
        <div class="result-review-status">
            <span class="status-pill ${pillClass}">
                ${pillLabel}
            </span>
            <span class="rail-label">
                ${railMessage}
            </span>
        </div>
        <div class="result-review-grid">
            <section class="result-review-card">
                <strong>Receipt</strong>
                <ul>
                    ${fieldItem('receipt id', receiptId, { code: true })}
                    ${fieldItem('state', provider.provider_signed_url_state)}
                    ${fieldItem('expires at', expiresAt)}
                    ${fieldItem('delivery mode', provider.delivery_mode)}
                    ${fieldItem('url redacted', provider.provider_url_redacted, { code: true })}
                </ul>
            </section>
            ${recipientScope ? `<section class="result-review-card">
                <strong>Recipient</strong>
                <ul>${fieldItem('scope', recipientScope, { code: true })}</ul>
            </section>` : ''}
            <section class="result-review-card">
                <strong>Still Disabled</strong>
                <div class="downstream-locks">${renderDownstreamLocks([
                    'value_reveal',
                    'provider_network_write',
                    'connector_dispatch',
                    'raw_token_display',
                    'byte_streaming',
                    'production_readiness',
                ])}</div>
            </section>
            ${renderErrorCard(fetchError)}
        </div>
        <div class="provider-private-download-control-actions">
            <label class="provider-private-download-confirmation-label">
                <input
                    id="provider-private-download-confirmation"
                    type="checkbox"
                    class="provider-private-download-confirmation"
                    ${isPending ? 'disabled' : ''}
                >
                I confirm I am the intended recipient operator for this signed-URL package delivery.
            </label>
            <button
                id="provider-private-download-arm-btn"
                class="secondary-btn provider-private-download-arm-btn"
                type="button"
                ${isPending ? 'disabled' : ''}
            >${isPending ? 'Fetching status…' : 'Arm Download Link'}</button>
            ${hasInMemoryUrl ? `
            <a
                id="provider-private-download-anchor"
                class="provider-private-download-anchor primary-btn"
                href="#"
                data-receipt-id="${escapeHtml(receiptId)}"
                download
                aria-label="Download provider-private package (URL set at click time from in-memory receipt)"
            >Download Package</a>` : ''}
        </div>
    `;

    // Wire the arm button after innerHTML is set.
    const armBtn = panel.querySelector('#provider-private-download-arm-btn');
    const confirmCheck = panel.querySelector('#provider-private-download-confirmation');
    const anchor = panel.querySelector('#provider-private-download-anchor');

    if (armBtn) {
        armBtn.addEventListener('click', () => {
            if (!confirmCheck?.checked) return;
            armProviderPrivateDownloadAnchor();
        });
    }
    if (confirmCheck) {
        confirmCheck.addEventListener('change', () => {
            if (armBtn) armBtn.disabled = !confirmCheck.checked || isPending;
        });
    }

    // Set href at click time only — never render the URL as text.
    if (anchor && State.providerPrivateDownloadAnchorUrl) {
        anchor.addEventListener('click', (event) => {
            // Retrieve URL from in-memory state (not from DOM), set href just before navigation.
            const url = State.providerPrivateDownloadAnchorUrl;
            if (!url) {
                event.preventDefault();
                return;
            }
            anchor.href = url;
            // Revoke after a tick so the browser can start the download.
            setTimeout(() => {
                // Clear the in-memory URL after use — single-use delivery.
                State.providerPrivateDownloadAnchorUrl = null;
                renderProviderPrivateDownloadControlPanel();
            }, 500);
        });
    }
}

/**
 * Fetches the latest provider-private signed URL status to arm the download anchor.
 * The URL is stored ONLY in State.providerPrivateDownloadAnchorUrl (in-memory).
 * Never written to localStorage/sessionStorage, never logged, never rendered as text.
 */
async function armProviderPrivateDownloadAnchor() {
    if (!providerPrivateDownloadControlAuthorityPresent()) return;
    const receiptId = providerPrivateSignedUrlReceiptId();
    if (!receiptId) return;
    State.providerPrivateDownloadPending = true;
    State.providerPrivateDownloadError = null;
    State.providerPrivateDownloadRedactedNotice = null;
    renderProviderPrivateDownloadControlPanel();
    try {
        const statusPath = providerPrivateSignedUrlStatusPath();
        const response = (
            providerPrivateSignedUrlUsesSourceDirectoryPackageFamily()
            || providerPrivateSignedUrlUsesSourceDirectoryHybridFamily()
        )
            ? await postJson(statusPath, providerPrivateSignedUrlStatusPayload())
            : await getJson(statusPath);
        // The response contains provider_url_redacted but NOT the raw URL in normal flow.
        // For the fake provider in the test environment, we record that the arm was performed.
        // In a real provider integration, the raw URL would be a field returned only here.
        // We store only what the server returns — if it returns a download URL field,
        // it goes to in-memory state only. If not (redacted), we mark as armed with receipt-id.
        const rawDownloadUrl = response.provider_download_url || response.signed_url || null;
        State.providerPrivateSignedUrlStatus = response;
        if (rawDownloadUrl) {
            // Real URL present — arm the anchor. Store in-memory only; never log or persist.
            State.providerPrivateDownloadAnchorUrl = rawDownloadUrl;
            addEvent(`Provider-private download anchor armed for receipt ${receiptId.slice(0, 12)}…`);
        } else {
            // No real URL exposed (normal redacted posture) — do NOT arm the anchor.
            // Render an honest status rather than presenting a non-functional armed state.
            State.providerPrivateDownloadAnchorUrl = null;
            State.providerPrivateDownloadRedactedNotice = 'redacted — no download URL exposed by server';
            addEvent(`Provider-private download: redacted posture — no URL returned by server for receipt ${receiptId.slice(0, 12)}…`);
        }
        renderAll();
    } catch (error) {
        State.providerPrivateDownloadError = error.payload || {
            error_code: 'provider_private_download_arm_failed',
            message: error.message,
        };
        State.providerPrivateDownloadAnchorUrl = null;
        addEvent(`Provider-private download arm blocked: ${error.message}`);
        renderProviderPrivateDownloadControlPanel();
    } finally {
        State.providerPrivateDownloadPending = false;
        renderProviderPrivateDownloadControlPanel();
    }
}

