elements.candidateBDefaultPromotionStatusPanel.addEventListener('click', (event) => {
    inspectCandidateBFullCorpusOperatorWorkflowHistoryRow(event);
    expireCandidateBFullCorpusOperatorWorkflowHistoryRow(event);
    recordCandidateBFullCorpusOperatorWorkflowQueueState(event);
    recordCandidateBFullCorpusOperatorWorkflowExecutionBoundary(event);
    recordCandidateBFullCorpusOperatorWorkflowProcessExecution(event);
    recordCandidateBFullCorpusOperatorWorkflowProcessCompletionResult(event);
    recordCandidateBFullCorpusOperatorWorkflowAdoptedResultDownstreamProof(event);
    inspectCandidateBFullCorpusOperatorWorkflowCompletionMonitor(event);
    recordCandidateBFullCorpusOperatorRepeatabilityCheckpoint(event);
    recordCandidateBFullCorpusRepeatabilityRerunTrial(event);
    recordCandidateBFullCorpusRepeatabilityAcceptanceCheckpoint(event);
    recordCandidateBFullCorpusRepeatabilityAcceptanceCloseout(event);
    inspectCandidateBFullCorpusRepeatabilityAcceptanceCloseoutStatus(event);
});
